void sig_handler(int s) {
    // Signal handlers are copied (inherited)
    // Child and Parent execute this same function
}

struct sigaction sa;
sa.sa_handler = sig_handler;
sigemptyset(&sa.sa_mask);
sa.sa_flags = 0;

// Set disposition BEFORE fork()
sigaction(SIGUSR1, &sa, NULL);

pid_t pid = fork();

if (pid == 0) {
    // Child inherits the custom handler for SIGUSR1.
    // Child can optionally change its own handler post-fork.
    // signal(SIGUSR1, SIG_IGN); // Example override
}

// Parent continues. Both processes share the original disposition.
